                        self.saddled.retain(|e| e.4 == turn);
                        self.saddled.push((src, mz, r, rz, turn));
                        // The other creatures that saddled it with the named one.
                        let others = self
                            .saddle_extra
                            .iter()
                            .position(|e| e.0 == src)
                            .map(|i| self.saddle_extra.remove(i).1)
                            .unwrap_or_default();
